for(const [id,count]of Object.entries(PRACTICE_PACK_COUNTS)){const base=BANK[id];practiceBaseBanks[id]=base;practiceStarts[id]=base.length;const target=base.slice();target.length=base.length+count;BANK[id]=new Proxy(target,{get(t,p,r){if(typeof p==='string'&&/^\d+$/.test(p)){const i=Number(p);if(i>=base.length&&i<t.length)return practiceEntry(id,i-base.length)}return Reflect.get(t,p,r)},has(t,p){return typeof p==='string'&&/^\d+$/.test(p)&&Number(p)<t.length||Reflect.has(t,p)}})}
function practiceYear(t){return t<=3?6:t<=6?7:t<=8?8:t<=10?9:t<=12?10:t<=14?11:12}
const practiceTierPools={};
for(const s of SUBJECTS){const list=practiceBaseBanks[s.id]||BANK[s.id];practiceTierPools[s.id]=Array.from({length:18},()=>[]);list.forEach((q,index)=>practiceTierPools[s.id][Math.min(17,itemDifficulty({q}))].push(index))}
// Choose indexes first. A normal round materialises a small candidate pool, never all 50,000 entries.
buildQuestionDeck=function(subject){const ids=[...new Set(Array.isArray(subject)?subject:subject==='mixed'?SUBJECTS.map(s=>s.id):[subject])].filter(id=>BANK[id]),tier=questionStage().tier,groups=[];initialiseQuestionHistory();for(const id of ids){const seen=profile.questionSeen,chosen=[],used=new Set(),pools=practiceTierPools[id],count=PRACTICE_PACK_COUNTS[id]||0,start=practiceStarts[id]||0,add=index=>{if(!used.has(index)&&!seen[id+':'+index]){used.add(index);chosen.push(index)}};const tiers=Array.from({length:17},(_,i)=>i+1).sort((a,b)=>Math.abs(a-tier)+(a>tier?1:0)-Math.abs(b-tier)-(b>tier?1:0));for(const t of tiers){if(practiceYear(t)>questionStage().year)continue;const authored=(pools[t]||[]).filter(index=>((practiceBaseBanks[id]||BANK[id])[index][8]||6)<=questionStage().year),variants=count?Math.max(0,Math.floor((count-t)/17)+1):0;const total=authored.length+variants;if(!total)continue;const offset=Math.floor(Math.random()*total);for(let j=0;j<total&&chosen.length<32;j++){const k=(offset+j)%total;add(k<authored.length?authored[k]:start+t-1+(k-authored.length)*17)}if(chosen.length>=32)break}if(chosen.length<32){const old=Object.keys(seen).filter(k=>k.startsWith(id+':')).sort((a,b)=>seen[a]-seen[b]);for(const key of old){const index=Number(key.split(':')[1]);if(index<BANK[id].length&&!used.has(index)){used.add(index);chosen.push(index);if(chosen.length>=32)break}}}groups.push(chosen.map(index=>({id,index,q:BANK[id][index]})))}return weaveQuestions(groups)};
