const libraryParents=parents;parents=function(){return libraryParents().replace(/12,106 questions/g,'50,050 questions').replace('The bank contains 50,050 questions and calculated variations.','The bank contains 50,050 questions and calculated variations. Of these, 37,850 additional entries are deterministic numerical practice variations produced on demand from fixed skill templates. These are not 50,050 individually authored facts. Only a small candidate set is prepared for a round, with no extra question download during play.')};
