// Compact per-bank answer ledger: signed UTC minutes (positive correct, negative incorrect).
// Ceiling to the next minute ensures a wrong answer waits at least 48 full hours.
const QUESTION_RETRY_MS=48*60*60*1000,QUESTION_MASTERED_MS=7*24*60*60*1000;
function ensureQuestionMemory(){if(!profile.questionMemory||typeof profile.questionMemory!=='object'||Array.isArray(profile.questionMemory))profile.questionMemory={};if(!profile.questionMemoryVersion){const missed=new Set(profile.missed||[]),stamp=Math.ceil(Date.now()/60000);for(const key of Object.keys(profile.questionSeen||{})){const[id,n]=key.split(':'),index=Number(n);if(BANK[id]&&Number.isInteger(index)&&index>=0&&index<BANK[id].length){profile.questionMemory[id]??=[];profile.questionMemory[id][index]=(missed.has(key)?-1:1)*stamp}}profile.questionMemoryVersion=1;save()}}
function questionMemoryState(id,index,now=Date.now()){if(id==='history'&&HISTORY_RETIRED.has(index))return 'waiting';const stamp=profile.questionMemory?.[id]?.[index]||0;if(!stamp)return 'fresh';const delay=stamp<0?QUESTION_RETRY_MS:QUESTION_MASTERED_MS;return now<Math.abs(stamp)*60000+delay?'waiting':stamp<0?'review':'mastered'}
