const answerBeforeMemory=answer;answer=function(n){if(!quiz||quiz.answered)return;const item=quiz.item,correct=n>=0&&quiz.options[n]?.i===item.q[2];ensureQuestionMemory();profile.questionMemory[item.id]??=[];profile.questionMemory[item.id][item.index]=(correct?1:-1)*Math.ceil(Date.now()/60000);answerBeforeMemory(n);save()};
// Index-only selection uses three queues: unseen first, eligible mistakes second, mastered last.
buildQuestionDeck=function(subject){ensureQuestionMemory();const ids=[...new Set(Array.isArray(subject)?subject:subject==='mixed'?SUBJECTS.map(s=>s.id):[subject])].filter(id=>BANK[id]),tier=questionStage().tier,groups=[];const now=Date.now();for(const id of ids){const pools=practiceTierPools[id],count=PRACTICE_PACK_COUNTS[id]||0,start=practiceStarts[id]||0,buckets={fresh:[],review:[],mastered:[]};const tiers=Array.from({length:17},(_,i)=>i+1).sort((a,b)=>(Math.abs(a-tier)+(a>tier?1:0))-(Math.abs(b-tier)+(b>tier?1:0)));for(const t of tiers){if(practiceYear(t)>questionStage().year)continue;const authored=(pools[t]||[]).filter(index=>((practiceBaseBanks[id]||BANK[id])[index][8]||6)<=questionStage().year),variants=count?Math.max(0,Math.floor((count-t)/17)+1):0,total=authored.length+variants;if(!total)continue;const offset=Math.floor(Math.random()*total);for(let j=0;j<total;j++){const k=(offset+j)%total,index=k<authored.length?authored[k]:start+t-1+(k-authored.length)*17,state=questionMemoryState(id,index,now);if(state!=='waiting'&&buckets[state].length<32)buckets[state].push(index)}if(buckets.fresh.length>=32)break}groups.push(buckets)}const result=[];for(const state of ['fresh','review','mastered'])result.push(...weaveQuestions(groups.map((b,i)=>b[state].map(index=>({id:ids[i],index,q:BANK[ids[i]][index]})))));return result};
function libraryRoundReady(ids,keys){ensureQuestionMemory();if(keys){if(keys.some(key=>{const[id,n]=key.split(':');return questionMemoryState(id,Number(n))==='waiting'})){toast('This shared round includes a question still resting. Try another room or a fresh topic mix.');return false}return true}if(buildQuestionDeck(ids).length<10){toast('Not enough rested questions for ten yet. Add more fields, or return after the review waiting period.');return false}return true}
const libraryLaunch=launchConfiguredRound;launchConfiguredRound=function(){if(libraryRoundReady(fieldBanks(topicDraft)))return libraryLaunch()};
const libraryArena=startArena;startArena=function(subject){if(!libraryRoundReady(subject==='mixed'?(profile.battleTopics||['maths']):[subject],activeInvite?.keys))return;return libraryArena(subject)};
const libraryPractice=startPractice;startPractice=function(subject,review=false){ensureQuestionMemory();if(review){const deck=(profile.missed||[]).map(key=>{const[id,n]=key.split(':');return{id,index:Number(n)}}).filter(x=>BANK[x.id]&&questionMemoryState(x.id,x.index)==='review').map(x=>({...x,q:BANK[x.id][x.index]}));if(!deck.length){toast('Your missed questions are resting for at least 48 hours. Try fresh questions in another field.');return}clearQuestionClock();closeModal();quiz={mode:'practice',deck:shuffle(deck).slice(0,10),pos:0,right:0,subject,timed:!!profile.questionTimed};ask();return}const ids=Array.isArray(subject)?subject:subject==='mixed'?fieldBanks(selectedFields()):fieldBanks([subject]);if(libraryRoundReady(ids.length?ids:['maths']))return libraryPractice(subject,false)};
const libraryLiveStart=startLiveQuestions;startLiveQuestions=function(){if(!libraryRoundReady([],live?.config?.keys)){live.roundStarted=true;openModal(`${topModal('QUESTION REST PERIOD')}<h2 id="modal-title">Try a fresh crew challenge.</h2><p class="sub">This room includes a question you answered recently. Incorrect answers rest for at least 48 hours; correctly answered questions rest for seven days. Ask the host to create a different topic mix.</p><button class="primary" data-live="leave">Leave room</button>`);return}return libraryLiveStart()};
