const libraryInfo=parents;parents=function(){return libraryInfo()+'<section class="info-panel"><h2>Questions that remember your learning</h2><p>Unanswered questions come first. Incorrect answers wait at least 48 hours before review. Correct answers wait seven days and are used only after available fresh questions and eligible mistakes. If a small selected field has fewer than ten available questions, choose more fields or return later. The same rest rules apply to shared question rounds. Older saves have no answer timestamps, so their rest periods begin when this feature first reads the save. Optional account saving carries this history between devices.</p></section>'};


function seniorMemoryIndex(year,q){return SENIOR_BANK[year].indexOf(q)}
startSenior=function(year){if(!SENIOR_BANK[year]||game||live||quiz)return;ensureQuestionMemory();const id='senior'+year;profile.questionMemory[id]??=[];const memory=profile.questionMemory[id];SENIOR_BANK[year].forEach((q,i)=>{if(!memory[i]&&profile.seniorHistory?.[q.id])memory[i]=Math.ceil(profile.seniorHistory[q.id]/60000)});const groups={fresh:[],review:[],mastered:[]};for(const q of shuffle([...SENIOR_BANK[year]])){const state=questionMemoryState(id,seniorMemoryIndex(year,q));if(state!=='waiting')groups[state].push(q)}const available=[...groups.fresh,...groups.review,...groups.mastered];if(available.length<5){toast('These challenge questions are resting. Choose another year or return after the review waiting period.');return}const chosen=[],families=new Set();for(const state of ['fresh','review','mastered']){for(const q of groups[state])if(chosen.length<5&&!families.has(q.family)){chosen.push(q);families.add(q.family)}for(const q of groups[state])if(chosen.length<5&&!chosen.includes(q))chosen.push(q);if(chosen.length>=5)break}seniorRound={year,deck:chosen,pos:0,right:0,answered:false};showSeniorQuestion()};
